<script>
import { isNotEmpty } from '@primeuix/utils';
import BaseComponent from '@primevue/core/basecomponent';

export default {
    name: 'BaseEditableHolder',
    extends: BaseComponent,
    emits: ['update:modelValue', 'value-change'],
    props: {
        modelValue: {
            type: null,
            default: undefined
        },
        defaultValue: {
            type: null,
            default: undefined
        },
        name: {
            type: String,
            default: undefined
        },
        invalid: {
            type: Boolean,
            default: undefined
        },
        disabled: {
            type: Boolean,
            default: false
        },
        formControl: {
            type: Object,
            default: undefined
        }
    },
    inject: {
        $parentInstance: {
            default: undefined
        },
        $pcForm: {
            default: undefined
        },
        $pcFormField: {
            default: undefined
        }
    },
    data() {
        return {
            d_value: this.defaultValue !== undefined ? this.defaultValue : this.modelValue,
            d_formDefaultApplied: false
        };
    },
    watch: {
        modelValue: {
            deep: true,
            handler(newValue) {
                this.d_value = newValue;
            }
        },
        defaultValue(newValue) {
            this.d_value = newValue;
        },
        $formName: {
            immediate: true,
            handler(newValue) {
                this.formField = this.$pcForm?.register?.(newValue, this.$formControl) || {};
            }
        },
        $formControl: {
            immediate: true,
            handler(newValue) {
                this.formField = this.$pcForm?.register?.(this.$formName, newValue) || {};
            }
        },
        $formDefaultValue: {
            immediate: true,
            handler(newValue) {
                // Seed d_value with the form/default value only once. $formDefaultValue falls back to
                // the form's initialValues whenever d_value is empty, so re-applying it on every change
                // would restore the initial value and make the field impossible to clear (e.g. an input
                // inside a <Form> with initialValues). Applying it once keeps the original precedence
                // (the component's own value wins) without the clear-bug feedback loop.
                if (this.d_formDefaultApplied || !isNotEmpty(newValue)) return;

                this.d_formDefaultApplied = true;
                this.d_value !== newValue && (this.d_value = newValue);
            }
        },
        $formValue: {
            immediate: false,
            handler(newValue) {
                if (this.$pcForm?.getFieldState(this.$formName) && newValue !== this.d_value) {
                    this.d_value = newValue;
                }
            }
        }
    },
    formField: {},
    methods: {
        writeValue(value, event) {
            if (this.controlled) {
                this.d_value = value;
                this.$emit('update:modelValue', value);
            }

            this.$emit('value-change', value);

            this.formField.onChange?.({ originalEvent: event, value });
        },
        // @todo move to @primeuix/utils
        findNonEmpty(...values) {
            return values.find(isNotEmpty);
        }
    },
    computed: {
        $filled() {
            return isNotEmpty(this.d_value);
        },
        $invalid() {
            // `novalidate` opts the field OUT of reading form validation state, but an explicitly
            // passed `invalid` prop must still apply (e.g. a composite's inner input that uses
            // novalidate to avoid double-registration yet still mirrors the parent's invalid state).
            const formInvalid = this.$formNovalidate ? undefined : this.findNonEmpty(this.$pcFormField?.$field?.invalid, this.$pcForm?.getFieldState(this.$formName)?.invalid);

            return this.findNonEmpty(this.invalid, formInvalid);
        },
        $formName() {
            return !this.$formNovalidate ? this.name || this.$formControl?.name : undefined;
        },
        $formControl() {
            return this.formControl || this.$pcFormField?.formControl;
        },
        $formNovalidate() {
            return this.$formControl?.novalidate;
        },
        $formDefaultValue() {
            // The `getFieldState(...).value` fallback lets dotted/nested field names (e.g. "address.city")
            // seed from nested `initialValues`: the form resolves the path into the field state, whereas the
            // flat `initialValues[$formName]` lookup only matches top-level keys.
            return this.findNonEmpty(this.d_value, this.$pcFormField?.initialValue, this.$pcForm?.initialValues?.[this.$formName], this.$pcForm?.getFieldState(this.$formName)?.value);
        },
        $formValue() {
            return this.findNonEmpty(this.$pcFormField?.$field?.value, this.$pcForm?.getFieldState(this.$formName)?.value);
        },
        controlled() {
            return this.$inProps.hasOwnProperty('modelValue') || (!this.$inProps.hasOwnProperty('modelValue') && !this.$inProps.hasOwnProperty('defaultValue'));
        }
    }
};
</script>
